/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */
import { readFileSync } from 'node:fs'
import { scan, ScanError } from './scanner.js'

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}

let tokens
try {
  tokens = scan(readFileSync(0, 'utf8'))
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${e.line}:${e.col}: ${e.reason}\n`)
  process.exit(2)
}

let out = ''
if (args[0] === 'tokens') {
  for (const t of tokens) out += `${t.line}:${t.col} ${t.kind} ${t.body}\n`
} else {
  for (const k of ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']) {
    out += `${k} ${tokens.filter((t) => t.kind === k).length}\n`
  }
  out += `total ${tokens.length}\n`
}
process.stdout.write(out)
"}

